"""Integration tests for the OnboardingCoordinator."""

import pytest
from pathlib import Path
from unittest.mock import AsyncMock, MagicMock, patch

from kortex_mcp.coordinators.onboarding import (
    OnboardingCoordinator,
    OnboardingResult,
    RegenerateResult,
)
from kortex_mcp.generators.structure_generator import StructureMemoryGenerator
from kortex_mcp.generators.tech_stack_generator import TechStackMemoryGenerator
from kortex_mcp.generators.architecture_generator import ArchitectureMemoryGenerator


# Expected memory IDs generated by the coordinator
EXPECTED_MEMORY_IDS = [
    "project_structure",
    "tech_stack",
    "architecture",
    "dependencies",
    "android_platform",
    "ios_platform",
    "coding_patterns",
    "testing_setup",
]


@pytest.fixture
def sample_kmp_path(fixtures_dir: Path, tmp_path: Path) -> Path:
    """Get path to sample KMP project fixture (copied to temp dir).

    Args:
        fixtures_dir: Fixtures directory path
        tmp_path: Temporary directory path

    Returns:
        Path to sample KMP project in temp dir
    """
    import shutil
    source = fixtures_dir / "sample_kmp_project"
    dest = tmp_path / "sample_kmp_project"
    shutil.copytree(source, dest)
    return dest


@pytest.fixture
def sample_cmp_path(fixtures_dir: Path, tmp_path: Path) -> Path:
    """Get path to sample CMP project fixture (copied to temp dir).

    Args:
        fixtures_dir: Fixtures directory path
        tmp_path: Temporary directory path

    Returns:
        Path to sample CMP project in temp dir
    """
    import shutil
    source = fixtures_dir / "sample_cmp_project"
    dest = tmp_path / "sample_cmp_project"
    shutil.copytree(source, dest)
